type Statut = "en attente" | "payée" | "livrée";

function compter(statuts: Statut[]): Record<Statut, number> {
  const c: Record<Statut, number> = { "en attente": 0, "payée": 0, "livrée": 0 };
  for (const s of statuts) c[s]++;
  return c;
}

